require_once __DIR__ . '/../Response.php';
require_once __DIR__ . '/../SystemLog.php';
require_once __DIR__ . '/../Database.php';
require_once __DIR__ . '/../Utils/EntityVersion.php';

use App\Utils\EntityVersion;

class CategoriesController
{
    private static bool $columnsEnsured = false;
    private static bool $historyTableEnsured = false;

    private function ensureCategoriesColumns(PDO $db): void
    {
        if (self::$columnsEnsured) {
            return;
        }
        self::$columnsEnsured = true;
        $columns = [
            'uid' => 'VARCHAR(50) UNIQUE DEFAULT NULL',
            'picture' => 'LONGTEXT NULL',
            'picture_name' => 'VARCHAR(255) NULL',
            'color' => 'VARCHAR(50) DEFAULT NULL',
            'description' => 'TEXT NULL',
            'created_by' => 'INT NULL',
            'edited_by' => 'INT NULL',
            'deleted_at' => 'DATETIME NULL',
            'deleted_by' => 'INT NULL',
            'delete_reason' => 'TEXT NULL'
        ];

        $existingCols = [];
        try {
            $colStmt = $db->query("SHOW COLUMNS FROM categories");
            while ($colRow = $colStmt->fetch(PDO::FETCH_ASSOC)) {
                $existingCols[$colRow['Field']] = true;
            }
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }

        foreach ($columns as $column => $definition) {
            if (!isset($existingCols[$column])) {
                try {
                    $db->exec("ALTER TABLE categories ADD COLUMN $column $definition");
                } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
            }
        }

        try {
            $hasIdx = $db->query("SHOW INDEX FROM categories WHERE Key_name = 'idx_categories_deleted_id'")->fetch();
            if (!$hasIdx) {
                $db->exec("ALTER TABLE categories ADD INDEX idx_categories_deleted_id (deleted_at, id)");
            }
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
    }

    private function ensureCategoryHistoryTable(PDO $db): void
    {
        if (self::$historyTableEnsured) {
            return;
        }
        self::$historyTableEnsured = true;

        try {
            $db->exec("CREATE TABLE IF NOT EXISTS category_history (
                id INT AUTO_INCREMENT PRIMARY KEY,
                category_id INT NOT NULL,
                edited_by INT NULL,
                action VARCHAR(50) NOT NULL,
                changes JSON NULL,
                reason TEXT NULL,
                created_at DATETIME NOT NULL,
                INDEX idx_ch_cat_created (category_id, created_at),
                INDEX idx_ch_edited_by (edited_by),
                FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
                FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE SET NULL
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
    }

    public function index(): void
    {
        $db = Database::getConnection();
        $this->ensureCategoriesColumns($db);
        // Seed the pre-built default catalog once on a virgin DB (covers the current
        // already-installed fresh database on its first load). Idempotent. See index.php.
        if (function_exists('ensureDefaultCatalogSeeded')) {
            ensureDefaultCatalogSeeded($db);
        }
        $showDeleted = isset($_GET['show_deleted']) && $_GET['show_deleted'] === 'true';

        $selectFields = "id, uid, name, color, description, picture_name, created_by, edited_by, deleted_by, delete_reason, created_at, updated_at, deleted_at,
                         IF(picture IS NOT NULL AND picture != '', 1, 0) AS has_picture,
                         IF(picture IS NOT NULL AND picture != '', 
                            CONCAT('/api/categories/', id, '/image?v=', UNIX_TIMESTAMP(COALESCE(updated_at, created_at, NOW()))), 
                            NULL
                         ) AS picture";

        if ($showDeleted) {
            $categories = $db->query("SELECT $selectFields FROM categories ORDER BY id DESC")->fetchAll();
        } else {
            $categories = $db->query("SELECT $selectFields FROM categories WHERE deleted_at IS NULL ORDER BY id DESC")->fetchAll();
        }

        Response::json(['categories' => $categories]);
    }

    public function image(string $id): void
    {
        $db = Database::getConnection();
        $catId = (int)$id;
        $ifNoneMatch = $_SERVER['HTTP_IF_NONE_MATCH'] ?? '';
        $ifModifiedSince = $_SERVER['HTTP_IF_MODIFIED_SINCE'] ?? '';
        $cleanClientEtag = trim(preg_replace('/^W\//', '', trim($ifNoneMatch)), '"');

        // Early cache check: verify ETag & Last-Modified without loading heavy BLOB into memory
        if ($cleanClientEtag !== '' || !empty($ifModifiedSince)) {
            $metaStmt = $db->prepare('SELECT updated_at, created_at, SHA2(picture, 256) AS img_hash, CASE WHEN picture IS NOT NULL AND picture != "" THEN 1 ELSE 0 END AS has_picture FROM categories WHERE id = :id');
            $metaStmt->execute(['id' => $catId]);
            $meta = $metaStmt->fetch();

            if (!$meta || empty($meta['has_picture'])) {
                http_response_code(404);
                header('Content-Type: application/json');
                echo json_encode(['error' => 'Category image not found']);
                exit;
            }

            $lastModified = strtotime($meta['updated_at'] ?? $meta['created_at'] ?? 'now');
            $serverEtag = (string)($meta['img_hash'] ?? '');

            $etagMatches = ($cleanClientEtag !== '' && ($cleanClientEtag === $serverEtag || $cleanClientEtag === substr($serverEtag, 0, 32)));
            $timeMatches = (!empty($ifModifiedSince) && strtotime($ifModifiedSince) >= $lastModified);

            if ($etagMatches || ($cleanClientEtag === '' && $timeMatches)) {
                header('ETag: "' . $serverEtag . '"');
                header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $lastModified) . ' GMT');
                header('Cache-Control: public, max-age=31536000, immutable');
                http_response_code(304);
                exit;
            }
        }

        $stmt = $db->prepare('SELECT picture, updated_at, created_at FROM categories WHERE id = :id');
        $stmt->execute(['id' => $catId]);
        $cat = $stmt->fetch();

        if (!$cat || empty($cat['picture'])) {
            http_response_code(404);
            header('Content-Type: application/json');
            echo json_encode(['error' => 'Category image not found']);
            exit;
        }

        $raw = $cat['picture'];
        $binary = null;

        if (str_starts_with($raw, 'data:')) {
            $comma = strpos($raw, ',');
            if ($comma !== false) {
                $binary = base64_decode(substr($raw, $comma + 1), true);
            }
        } else {
            $binary = base64_decode($raw, true);
        }

        if ($binary === false || $binary === null || strlen($binary) <= 10) {
            http_response_code(404);
            header('Content-Type: application/json');
            echo json_encode(['error' => 'Invalid image data']);
            exit;
        }

        // Unconditionally validate magic bytes via finfo; return 404 for non-images
        $finfo = new finfo(FILEINFO_MIME_TYPE);
        $detected = $finfo->buffer($binary);
        if (!$detected) {
            http_response_code(404);
            header('Content-Type: application/json');
            echo json_encode(['error' => 'Invalid image format']);
            exit;
        }

        $allowedMimes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/bmp', 'image/x-icon'];
        $cleanMime = strtolower(trim((string)$detected));
        if (!in_array($cleanMime, $allowedMimes, true)) {
            http_response_code(404);
            header('Content-Type: application/json');
            echo json_encode(['error' => 'Invalid image format']);
            exit;
        }

        $serverEtag = hash('sha256', $raw);
        $etag = '"' . $serverEtag . '"';
        $lastModified = strtotime($cat['updated_at'] ?? $cat['created_at'] ?? 'now');

        if ($cleanClientEtag !== '' && ($cleanClientEtag === $serverEtag || $cleanClientEtag === substr($serverEtag, 0, 32))) {
            header('ETag: ' . $etag);
            header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $lastModified) . ' GMT');
            header('Cache-Control: public, max-age=31536000, immutable');
            http_response_code(304);
            exit;
        }

        header('Content-Type: ' . $cleanMime);
        header('Content-Length: ' . strlen($binary));
        header('ETag: ' . $etag);
        header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $lastModified) . ' GMT');
        header('Cache-Control: public, max-age=31536000, immutable');
        header('X-Content-Type-Options: nosniff');
        echo $binary;
        exit;
    }


    public function store(array $data): void
    {
        $name = trim($data['name'] ?? '');
        if ($name === '') {
            Response::json(['error' => 'Category name required'], 400);
            return;
        }

        if (mb_strlen($name) > 190) {
            Response::json(['error' => 'Category name cannot exceed 190 characters'], 400);
            return;
        }

        if (isset($data['color']) && mb_strlen((string)$data['color']) > 50) {
            Response::json(['error' => 'Color cannot exceed 50 characters'], 400);
            return;
        }

        $db = Database::getConnection();
        $this->ensureCategoriesColumns($db);
        $this->ensureCategoryHistoryTable($db);

        // Generate unique UID
        $uid = 'CAT-' . date('Ymd') . '-' . strtoupper(bin2hex(random_bytes(3)));

        $db->beginTransaction();
        try {
            $stmt = $db->prepare('INSERT INTO categories (uid, name, color, description, picture, picture_name, created_by, created_at) VALUES (:uid, :name, :color, :description, :picture, :picture_name, :created_by, NOW())');
            $stmt->execute([
                'uid' => $uid,
                'name' => $name,
                'color' => $data['color'] ?? null,
                'description' => $data['description'] ?? null,
                'picture' => $data['picture'] ?? null,
                'picture_name' => $data['picture_name'] ?? null,
                'created_by' => $_SESSION['user_id'] ?? null,
            ]);

            $categoryId = (int) $db->lastInsertId();

            // Log creation to history
            $historyStmt = $db->prepare('INSERT INTO category_history (category_id, edited_by, action, changes, created_at) VALUES (:category_id, :edited_by, :action, :changes, NOW())');
            $historyStmt->execute([
                'category_id' => $categoryId,
                'edited_by' => $_SESSION['user_id'] ?? null,
                'action' => 'created',
                'changes' => json_encode([
                    'name' => $name,
                    'color' => $data['color'] ?? null,
                    'description' => $data['description'] ?? null,
                    'picture_name' => $data['picture_name'] ?? null
                ])
            ]);

            EntityVersion::bump($db, 'categories');
            $db->commit();
        } catch (\Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            error_log('[CATEGORY CREATE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to create category. Please check server error logs.'], 500);
            return;
        }

        $createDetails = ['uid' => $uid, 'status' => 'active'];
        if ($data['color'] ?? null) $createDetails['color'] = $data['color'];
        if ($data['description'] ?? null) $createDetails['description'] = $data['description'];
        if ($data['picture_name'] ?? null) $createDetails['picture'] = $data['picture_name'];
        SystemLog::write('categories', 'created', $categoryId, $name, json_encode($createDetails));

        Response::json(['id' => $categoryId], 201);
    }


