​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */
        if (array_key_exists('name', $data)) {
            if (trim((string)$data['name']) === '') {
                Response::json(['error' => 'Category name cannot be empty'], 400);
                return;
            }
            if (mb_strlen(trim((string)$data['name'])) > 190) {
                Response::json(['error' => 'Category name cannot exceed 190 characters'], 400);
                return;
            }
            $data['name'] = trim((string)$data['name']);
        }

        if (isset($data['color']) && mb_strlen((string)$data['color']) > 50) {
            Response::json(['error' => 'Color cannot exceed 50 characters'], 400);
            return;
        }

        // If incoming picture is a streaming URL or unchanged reference, do not overwrite database BLOB/base64
        if (isset($data['picture']) && is_string($data['picture']) && (
            str_contains($data['picture'], '/image') ||
            str_starts_with($data['picture'], '/api/') ||
            str_contains($data['picture'], '/api/categories/') ||
            str_starts_with($data['picture'], 'http://') ||
            str_starts_with($data['picture'], 'https://')
        )) {
            unset($data['picture']);
            unset($data['picture_name']);
        }

        $db->beginTransaction();
        try {
            $stmt = $db->prepare('SELECT * FROM categories WHERE id = :id FOR UPDATE');
            $stmt->execute(['id' => $id]);
            $category = $stmt->fetch();
            if (!$category) {
                $db->rollBack();
                Response::json(['error' => 'Category not found'], 404);
                return;
            }

            if ($category['deleted_at'] !== null) {
                $db->rollBack();
                Response::json(['error' => 'Cannot modify a deleted category. Restore it first.'], 400);
                return;
            }

            // Track changes
            $changes = [];
            $fields = ['name', 'color', 'description', 'picture'];
            foreach ($fields as $field) {
                if (array_key_exists($field, $data)) {
                    $newValue = $data[$field];
                    $oldValue = $category[$field];

                    // Normalize for comparison
                    $normalizedNew = ($newValue === '' || $newValue === null) ? null : $newValue;
                    $normalizedOld = ($oldValue === '' || $oldValue === null) ? null : $oldValue;

                    if ($field === 'picture') {
                        $picDataChanged = ($normalizedNew !== $normalizedOld);
                        $picNameChanged = ($normalizedNew !== null && array_key_exists('picture_name', $data) && ($data['picture_name'] ?? null) !== $category['picture_name']);
                        if ($picDataChanged || $picNameChanged) {
                            $oldName = ($normalizedOld !== null) ? ($category['picture_name'] ?: '[image]') : 'empty';
                            $newName = ($normalizedNew !== null) ? (($data['picture_name'] ?? null) ?: '[image]') : 'empty';
                            if ($oldName !== $newName || $oldName !== 'empty') {
                                $changes['picture'] = ['from' => $oldName, 'to' => $newName];
                            }
                        }
                    } else if ((string) $normalizedNew !== (string) $normalizedOld) {
                        $changes[$field] = ['from' => $oldValue, 'to' => $newValue];
                    }
                }
            }

            $stmt = $db->prepare('UPDATE categories SET name = :name, color = :color, description = :description, picture = :picture, picture_name = :picture_name, edited_by = :edited_by, updated_at = NOW() WHERE id = :id');
            $stmt->execute([
                'name' => array_key_exists('name', $data) ? $data['name'] : $category['name'],
                'color' => array_key_exists('color', $data) ? $data['color'] : $category['color'],
                'description' => array_key_exists('description', $data) ? $data['description'] : $category['description'],
                'picture' => array_key_exists('picture', $data) ? $data['picture'] : $category['picture'],
                'picture_name' => array_key_exists('picture_name', $data) ? $data['picture_name'] : $category['picture_name'],
                'edited_by' => $_SESSION['user_id'] ?? null,
                'id' => $id,
            ]);

            // Log edit to history if there were changes
            if (!empty($changes)) {
                $historyStmt = $db->prepare('INSERT INTO category_history (category_id, edited_by, action, changes, created_at) VALUES (:category_id, :edited_by, :action, :changes, NOW())');
                $historyStmt->execute([
                    'category_id' => $id,
                    'edited_by' => $_SESSION['user_id'] ?? null,
                    'action' => 'updated',
                    'changes' => json_encode($changes)
                ]);
            }

            EntityVersion::bump($db, 'categories');
            $db->commit();
        } catch (\Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            error_log('[CATEGORY UPDATE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to update category. Please check server error logs.'], 500);
            return;
        }

        if (!empty($changes)) {
            SystemLog::write('categories', 'updated', (int)$id, $category['name'], json_encode(array_merge(
                ['uid' => $category['uid'] ?? null],
                $changes
            )));
        }

        Response::json(['ok' => true]);
    }


    public function destroy(string $id, ?array $data = null): void
    {
        $db = Database::getConnection();
        $this->ensureCategoriesColumns($db);
        $this->ensureCategoryHistoryTable($db);

        // Get deletion reason from request body or data array
        $input = $data ?? json_decode(file_get_contents('php://input'), true) ?? [];
        $deleteReason = trim($input['delete_reason'] ?? '');
        if ($deleteReason === '') {
            Response::json(['error' => 'Deletion reason is required'], 400);
            return;
        }

        $db->beginTransaction();
        try {
            $stmt = $db->prepare('SELECT id, name, uid, deleted_at FROM categories WHERE id = :id FOR UPDATE');
            $stmt->execute(['id' => $id]);
            $category = $stmt->fetch();
            if (!$category) {
                $db->rollBack();
                Response::json(['error' => 'Category not found'], 404);
                return;
            }

            if (!empty($category['deleted_at'])) {
                $db->rollBack();
                Response::json(['error' => 'Category is already deleted'], 400);
                return;
            }

            // Check for active (non-deleted) products in this category inside transaction (Rule 41 barrier)
            $stmt = $db->prepare('SELECT COUNT(*) as count FROM products WHERE category_id = :id AND deleted_at IS NULL');
            $stmt->execute(['id' => $id]);
            $count = (int) ($stmt->fetch()['count'] ?? 0);
            if ($count > 0) {
                $db->rollBack();
                Response::json(['error' => 'Cannot delete category. It has active products.', 'product_count' => $count], 400);
                return;
            }

            // Soft delete the category
            $stmt = $db->prepare('UPDATE categories SET deleted_at = NOW(), deleted_by = :deleted_by, delete_reason = :delete_reason WHERE id = :id');
            $stmt->execute([
                'deleted_by' => $_SESSION['user_id'] ?? null,
                'delete_reason' => $deleteReason,
                'id' => $id
            ]);

            // Log deletion to history
            $historyStmt = $db->prepare('INSERT INTO category_history (category_id, edited_by, action, reason, created_at) VALUES (:category_id, :edited_by, :action, :reason, NOW())');
            $historyStmt->execute([
                'category_id' => $id,
                'edited_by' => $_SESSION['user_id'] ?? null,
                'action' => 'deleted',
                'reason' => $deleteReason
            ]);

            EntityVersion::bump($db, 'categories');
            $db->commit();
        } catch (\Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            error_log('[CATEGORY DELETE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to delete category. Please check server error logs.'], 500);
            return;
        }

        SystemLog::write('categories', 'deleted', (int)$id, $category['name'], json_encode([
            'uid' => $category['uid'] ?? null,
            'reason' => $deleteReason,
            'status' => 'deleted'
        ]));

        Response::json(['ok' => true]);
    }

    public function restore(string $id, ?array $data = null): void
    {
        $db = Database::getConnection();
        $this->ensureCategoriesColumns($db);
        $this->ensureCategoryHistoryTable($db);

        $input = $data ?? json_decode(file_get_contents('php://input'), true) ?? [];
        $restoreReason = trim($input['restore_reason'] ?? '');
        if ($restoreReason === '') {
            Response::json(['error' => 'Restore reason is required'], 400);
            return;
        }

        $db->beginTransaction();
        try {
            $stmt = $db->prepare('SELECT id, name, uid, deleted_at FROM categories WHERE id = :id FOR UPDATE');
            $stmt->execute(['id' => $id]);
            $category = $stmt->fetch();
            if (!$category) {
                $db->rollBack();
                Response::json(['error' => 'Category not found'], 404);
                return;
            }

            if (empty($category['deleted_at'])) {
                $db->rollBack();
                Response::json(['error' => 'Category is already active'], 400);
                return;
            }

            // Restore: set deleted_at, deleted_by, delete_reason to NULL
            $stmt = $db->prepare('UPDATE categories SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id = :id');
            $stmt->execute(['id' => $id]);

            // Log restoration to history
            $historyStmt = $db->prepare('INSERT INTO category_history (category_id, edited_by, action, reason, created_at) VALUES (:category_id, :edited_by, :action, :reason, NOW())');
            $historyStmt->execute([
                'category_id' => $id,
                'edited_by' => $_SESSION['user_id'] ?? null,
                'action' => 'restored',
                'reason' => $restoreReason
            ]);

            EntityVersion::bump($db, 'categories');
            $db->commit();
        } catch (\Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            error_log('[CATEGORY RESTORE ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to restore category. Please check server error logs.'], 500);
            return;
        }

        SystemLog::write('categories', 'restored', (int)$id, $category['name'], json_encode([
            'uid' => $category['uid'] ?? null,
            'reason' => $restoreReason,
            'status' => 'active'
        ]));

        Response::json(['ok' => true]);
    }

    public function history(string $id): void
    {
        $db = Database::getConnection();
        $this->ensureCategoriesColumns($db);
        $this->ensureCategoryHistoryTable($db);

        // Get category info with creator, editor and deleter names (excluding heavy base64 image)
        $stmt = $db->prepare("SELECT c.id, c.uid, c.name, c.color, c.description, c.picture_name, c.created_by, c.edited_by, c.deleted_by, c.delete_reason, c.created_at, c.updated_at, c.deleted_at,
                              u_create.username AS creator_name,
                              u_edit.username AS editor_name,
                              u_del.username AS deleted_by_name,
                              IF(c.picture IS NOT NULL AND c.picture != '', 1, 0) AS has_picture,
                              IF(c.picture IS NOT NULL AND c.picture != '', 
                                 CONCAT('/api/categories/', c.id, '/image?v=', UNIX_TIMESTAMP(COALESCE(c.updated_at, c.created_at, NOW()))), 
                                 NULL
                              ) AS picture 
                              FROM categories c
                              LEFT JOIN users u_create ON c.created_by = u_create.id
                              LEFT JOIN users u_edit ON c.edited_by = u_edit.id
                              LEFT JOIN users u_del ON c.deleted_by = u_del.id
                              WHERE c.id = :id");
        $stmt->execute(['id' => $id]);
        $category = $stmt->fetch();
        if (!$category) {
            Response::json(['error' => 'Category not found'], 404);
            return;
        }

        // Get history with user information
        $stmt = $db->prepare('
            SELECT ch.*, u.username 
            FROM category_history ch
            LEFT JOIN users u ON ch.edited_by = u.id
            WHERE ch.category_id = :id
            ORDER BY ch.created_at DESC
        ');
        $stmt->execute(['id' => $id]);
        $history = $stmt->fetchAll();

        Response::json([
            'category' => $category,
            'history' => $history
        ]);
    }
}

